# ! [doc = " Generic hashing support."] # ! [doc = ""] # ! [doc = " This module provides a generic way to compute the [hash] of a value."] # ! [doc = " Hashes are most commonly used with [`HashMap`] and [`HashSet`]."] # ! [doc = ""] # ! [doc = " [hash]: https://en.wikipedia.org/wiki/Hash_function"] # ! [doc = " [`HashMap`]: ../../std/collections/struct.HashMap.html"] # ! [doc = " [`HashSet`]: ../../std/collections/struct.HashSet.html"] # ! [doc = ""] # ! [doc = " The simplest way to make a type hashable is to use `#[derive(Hash)]`:"] # ! [doc = ""] # ! [doc = " # Examples"] # ! [doc = ""] # ! [doc = " ```rust"] # ! [doc = " use std::hash::{DefaultHasher, Hash, Hasher};"] # ! [doc = ""] # ! [doc = " #[derive(Hash)]"] # ! [doc = " struct Person {"] # ! [doc = "     id: u32,"] # ! [doc = "     name: String,"] # ! [doc = "     phone: u64,"] # ! [doc = " }"] # ! [doc = ""] # ! [doc = " let person1 = Person {"] # ! [doc = "     id: 5,"] # ! [doc = "     name: \"Janet\".to_string(),"] # ! [doc = "     phone: 555_666_7777,"] # ! [doc = " };"] # ! [doc = " let person2 = Person {"] # ! [doc = "     id: 5,"] # ! [doc = "     name: \"Bob\".to_string(),"] # ! [doc = "     phone: 555_666_7777,"] # ! [doc = " };"] # ! [doc = ""] # ! [doc = " assert!(calculate_hash(&person1) != calculate_hash(&person2));"] # ! [doc = ""] # ! [doc = " fn calculate_hash<T: Hash>(t: &T) -> u64 {"] # ! [doc = "     let mut s = DefaultHasher::new();"] # ! [doc = "     t.hash(&mut s);"] # ! [doc = "     s.finish()"] # ! [doc = " }"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " If you need more control over how a value is hashed, you need to implement"] # ! [doc = " the [`Hash`] trait:"] # ! [doc = ""] # ! [doc = " ```rust"] # ! [doc = " use std::hash::{DefaultHasher, Hash, Hasher};"] # ! [doc = ""] # ! [doc = " struct Person {"] # ! [doc = "     id: u32,"] # ! [doc = "     # #[allow(dead_code)]"] # ! [doc = "     name: String,"] # ! [doc = "     phone: u64,"] # ! [doc = " }"] # ! [doc = ""] # ! [doc = " impl Hash for Person {"] # ! [doc = "     fn hash<H: Hasher>(&self, state: &mut H) {"] # ! [doc = "         self.id.hash(state);"] # ! [doc = "         self.phone.hash(state);"] # ! [doc = "     }"] # ! [doc = " }"] # ! [doc = ""] # ! [doc = " let person1 = Person {"] # ! [doc = "     id: 5,"] # ! [doc = "     name: \"Janet\".to_string(),"] # ! [doc = "     phone: 555_666_7777,"] # ! [doc = " };"] # ! [doc = " let person2 = Person {"] # ! [doc = "     id: 5,"] # ! [doc = "     name: \"Bob\".to_string(),"] # ! [doc = "     phone: 555_666_7777,"] # ! [doc = " };"] # ! [doc = ""] # ! [doc = " assert_eq!(calculate_hash(&person1), calculate_hash(&person2));"] # ! [doc = ""] # ! [doc = " fn calculate_hash<T: Hash>(t: &T) -> u64 {"] # ! [doc = "     let mut s = DefaultHasher::new();"] # ! [doc = "     t.hash(&mut s);"] # ! [doc = "     s.finish()"] # ! [doc = " }"] # ! [doc = " ```"] # ! [stable (feature = "rust1" , since = "1.0.0")] use split_decls_genesis :: ourprelude :: * ; pub (crate) mod random ; #[stable (feature = "rust1" , since = "1.0.0")] pub use core :: hash :: * ; #[stable (feature = "std_hash_exports" , since = "1.76.0")] pub use self :: random :: { DefaultHasher , RandomState } ;